CURRENT VISIT
Job ID: {{ $('Feedback webhook').first().json.body.job_id }}
Customer ID: {{ $('Feedback webhook').first().json.body.customer_id }}
Location: {{ $('Feedback webhook').first().json.body.location }}
Rating: {{ $('Feedback webhook').first().json.body.rating }}/5
Feedback: {{ $('Feedback webhook').first().json.body.feedback }}

PRIOR FEEDBACK RECORDS FOR THIS CUSTOMER
{{ JSON.stringify($items('Find customer feedback history').map(item => item.json).filter(row => row.job_id)) }}

Return the required structured assessment. The draft_response is only a proposed private reply for staff review.

parameters.jsCode:
const body = $('Feedback webhook').first().json.body;
const history = $items('Find customer feedback history').map(item => item.json).filter(row => row.job_id);
const ai = $json.output || $json;
const rating = Number(body.rating);
const text = String(body.feedback || '').toLowerCase();
const priorNegative = history.some(row => ['needs_follow_up', 'manager_escalation'].includes(String(row.route || '')) || Number(row.rating) <= 3);
const criticalSignal = /(unsafe|safety|injur|accident|brake|fire|fraud|stolen|theft|discriminat|harass|threat|lawyer|legal|police)/i.test(text);
const allowedRoutes = ['ready_to_review', 'needs_follow_up', 'manager_escalation'];
let route = allowedRoutes.includes(ai.route) ? ai.route : 'needs_follow_up';
if (rating <= 3 && route === 'ready_to_review') route = 'needs_follow_up';
if (rating <= 2 || criticalSignal || Number(ai.severity) >= 4 || priorNegative) route = 'manager_escalation';
return [{ json: {
  received_at: new Date().toISOString(),
  ...body,
  classification: String(ai.classification || 'complaint'),
  sentiment: String(ai.sentiment || 'neutral'),
  severity: Math.min(5, Math.max(1, Number(ai.severity) || 3)),
  repeat_concern: Boolean(ai.repeat_concern || priorNegative),
  route,
  summary: String(ai.summary || '').slice(0, 500),
  themes: Array.isArray(ai.themes) ? ai.themes.slice(0, 6).join(', ') : '',
  draft_response: String(ai.draft_response || '').slice(0, 1500),
  manager_note: String(ai.manager_note || '').slice(0, 750),
  ai_model: 'gpt-5-mini',
  human_review_status: 'pending',
  prior_feedback_count: history.length
} }];

